import { encodedLiteral, projectionFile } from "../rendering.js";
function render(definition, namespace) {
    if (definition.kind === "enum")
        throw new Error("The admitted C# profile does not project named enums.");
    const parameters = definition.fields.map((field) => `${field.type} ${field.name}${field.defaultLiteral === undefined ? "" : ` = ${field.defaultLiteral}`}`).join(",\n    ");
    const constants = definition.constants.map((constant) => `    public const string ${constant.name} = ${encodedLiteral("csharp", constant.value)};`).join("\n");
    const record = constants
        ? `public sealed record ${definition.typeName}(\n    ${parameters})\n{\n${constants}\n}\n`
        : `public sealed record ${definition.typeName}(\n    ${parameters});\n`;
    return `namespace ${namespace};\n\n` +
        `// Projected from kernel/schemas/${definition.sourcePointer.replace(/#$/, "")}.\n` +
        "// GENERATED by tools/src/projection/providers/csharp/structural-projection-provider.ts — do not hand-edit.\n" +
        record;
}
export class CSharpStructuralProjectionProvider {
    target = "csharp";
    render(graph, profile) {
        if (graph.target !== this.target || profile.language !== this.target)
            throw new Error("C# renderer received another target.");
        if (!profile.namespace)
            throw new Error("C# projection profile does not declare a namespace.");
        return {
            planType: "projection-plan.v1",
            target: this.target,
            outputDirectory: profile.outputDirectory,
            files: graph.definitions.map((definition) => projectionFile(`${definition.typeName}.cs`, render(definition, profile.namespace), definition))
        };
    }
}
